"use client"

import { type ReactNode, useCallback, useEffect, useMemo, useState } from "react"
import Link from "next/link"
import {
  ArrowLeft,
  BarChart3,
  Banknote,
  CalendarDays,
  CheckCircle2,
  ChevronRight,
  FileBarChart,
  Loader2,
  RefreshCw,
  Search,
  ShieldAlert,
  ShieldCheck,
  TriangleAlert,
  UserX,
} from "lucide-react"

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Skeleton } from "@/components/ui/skeleton"
import { Spinner } from "@/components/ui/spinner"
import { useAuth } from "@/hooks/useAuth"
import {
  ApiError,
  getBlacklistedClients,
  getBlacklistMonthlyReport,
  getPendingLiftRequests,
  liftBlacklist,
  rejectLiftRequest,
  type BlacklistReportDTO,
  type ClientBlacklistDTO,
  type PendingLiftRequestDTO,
} from "@/lib/api"
import { cn } from "@/lib/utils"

const monthLabels = [
  "Janvier",
  "Fevrier",
  "Mars",
  "Avril",
  "Mai",
  "Juin",
  "Juillet",
  "Aout",
  "Septembre",
  "Octobre",
  "Novembre",
  "Decembre",
]

function formatDate(value: string | null | undefined) {
  if (!value) {
    return "-"
  }
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) {
    return value
  }
  return date.toLocaleString("fr-FR", {
    day: "2-digit",
    month: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  })
}

function formatMoney(value: number | null | undefined) {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return "0.00 DH"
  }
  return `${value.toFixed(2)} DH`
}

function formatToday() {
  return new Date().toLocaleDateString("fr-FR", {
    weekday: "long",
    day: "2-digit",
    month: "long",
    year: "numeric",
  })
}

function currentMonthInput() {
  const now = new Date()
  return {
    month: now.getMonth() + 1,
    year: now.getFullYear(),
  }
}

function emptyValue(value: string | number | null | undefined) {
  if (value === null || value === undefined || value === "") {
    return "-"
  }
  return String(value)
}

function getClientLabel(client: ClientBlacklistDTO) {
  return client.email || client.phone || `Client #${client.client_id}`
}

function csvCell(value: string | number | null | undefined) {
  const rawValue = value === null || value === undefined ? "" : String(value)
  return `"${rawValue.replace(/"/g, '""')}"`
}

function exportCSV(report: BlacklistReportDTO, mois: number, annee: number) {
  const lines: string[] = []

  lines.push("=== PAR CLIENT ===")
  lines.push("Client,Téléphone,Nb refus,Montant perdu (DH)")
  report.par_client.forEach((row) => {
    lines.push([
      csvCell(row.email || `Client #${row.client_id}`),
      csvCell(row.phone),
      csvCell(row.nb_refus),
      csvCell(row.montant_perdu),
    ].join(","))
  })

  lines.push("")
  lines.push("=== PAR LIVREUR ===")
  lines.push("Livreur,Nb refus")
  report.par_livreur.forEach((row) => {
    lines.push([
      csvCell(row.livreur_nom || `Livreur #${row.livreur_id}`),
      csvCell(row.nb_refus),
    ].join(","))
  })

  lines.push("")
  lines.push("=== COMMANDES REFUSEES ===")
  lines.push("Commande,Client,Téléphone,Date refus,Livreur,Quartier,Motif,Perte (DH)")
  report.commandes_refusees.forEach((row) => {
    lines.push([
      csvCell(row.commande_id),
      csvCell(row.client_label || `Client #${row.client_id}`),
      csvCell(row.phone),
      csvCell(row.date_refus),
      csvCell(row.livreur_nom),
      csvCell(row.quartier),
      csvCell(row.motif),
      csvCell(row.montant_perdu),
    ].join(","))
  })

  const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = `blacklist_${annee}_${String(mois).padStart(2, "0")}.csv`
  link.click()
  URL.revokeObjectURL(url)
}

function KpiCard({
  icon: Icon,
  label,
  value,
  helper,
  tone = "green",
}: {
  icon: typeof UserX
  label: string
  value: number | string
  helper?: string
  tone?: "green" | "red" | "orange" | "blue"
}) {
  const toneClasses = {
    green: "bg-[#F0FAF1] text-[#1E8A3C] border-emerald-100",
    red: "bg-red-50 text-red-700 border-red-100",
    orange: "bg-orange-50 text-[#F07C00] border-orange-100",
    blue: "bg-blue-50 text-[#1A4F8A] border-blue-100",
  }

  return (
    <div className="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md">
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-sm font-medium text-gray-500">{label}</p>
          <p className="mt-2 text-2xl font-bold tracking-tight text-gray-950">{value}</p>
          {helper ? <p className="mt-1 text-xs text-gray-400">{helper}</p> : null}
        </div>
        <div className={cn("rounded-xl border p-2.5", toneClasses[tone])}>
          <Icon className="h-5 w-5" />
        </div>
      </div>
    </div>
  )
}

function TableSkeleton({ columns = 6, rows = 5 }: { columns?: number; rows?: number }) {
  if (columns === 6) {
    return (
      <div className="divide-y divide-gray-100">
        {Array.from({ length: rows }).map((_, rowIndex) => (
          <div key={rowIndex} className="flex items-center gap-4 px-5 py-4 animate-pulse">
            <div className="h-4 bg-gray-200 rounded w-1/4" />
            <div className="h-4 bg-gray-200 rounded w-1/5" />
            <div className="h-6 bg-gray-200 rounded-full w-20" />
            <div className="h-4 bg-gray-200 rounded w-1/6" />
            <div className="ml-auto h-8 bg-gray-200 rounded-lg w-20" />
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className="animate-pulse space-y-3 p-6">
      {Array.from({ length: rows }).map((_, rowIndex) => (
        <div
          key={rowIndex}
          className="grid gap-3"
          style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}
        >
          {Array.from({ length: columns }).map((__, columnIndex) => (
            <Skeleton key={columnIndex} className="h-4 rounded bg-gray-200" />
          ))}
        </div>
      ))}
    </div>
  )
}

function SectionShell({
  children,
  className,
}: {
  children: ReactNode
  className?: string
}) {
  return (
    <section className={cn("overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm", className)}>
      {children}
    </section>
  )
}

function EmptyState({
  icon: Icon,
  title,
  description,
}: {
  icon: typeof UserX
  title: string
  description: string
}) {
  return (
    <div className="px-6 py-16 text-center">
      <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#F0FAF1] text-[#1E8A3C]">
        <Icon className="h-6 w-6" />
      </div>
      <p className="mt-4 text-base font-semibold text-gray-950">{title}</p>
      <p className="mx-auto mt-2 max-w-md text-sm leading-6 text-gray-500">{description}</p>
    </div>
  )
}

function SourceBadge({ source }: { source: string | null }) {
  const normalized = (source || "").toUpperCase()

  if (normalized === "AUTO_REFUS") {
    return (
      <span className="inline-flex items-center rounded-full border border-red-200 bg-red-50 px-3 py-1 text-xs font-medium text-red-700">
        Automatique
      </span>
    )
  }

  if (normalized === "ADMIN") {
    return (
      <span className="inline-flex items-center rounded-full border border-blue-200 bg-blue-50 px-3 py-1 text-xs font-medium text-blue-700">
        Admin
      </span>
    )
  }

  return (
    <span className="inline-flex items-center rounded-full border border-gray-200 bg-gray-50 px-3 py-1 text-xs font-medium text-gray-600">
      Inconnu
    </span>
  )
}

function BlacklistBadge() {
  return (
    <span className="inline-flex items-center rounded-full border border-red-200 bg-red-50 px-2.5 py-0.5 text-xs font-medium text-red-700">
      Blackliste
    </span>
  )
}

export default function AdminBlacklistPage() {
  const { token } = useAuth()
  const initialMonth = currentMonthInput()
  const [clients, setClients] = useState<ClientBlacklistDTO[]>([])
  const [pendingRequests, setPendingRequests] = useState<PendingLiftRequestDTO[]>([])
  const [report, setReport] = useState<BlacklistReportDTO | null>(null)
  const [month, setMonth] = useState(initialMonth.month)
  const [year, setYear] = useState(initialMonth.year)
  const [search, setSearch] = useState("")
  const [sourceFilter, setSourceFilter] = useState("")
  const [activeSection, setActiveSection] = useState<"liste" | "rapport">("liste")
  const [error, setError] = useState("")
  const [toast, setToast] = useState("")
  const [isLoadingClients, setIsLoadingClients] = useState(true)
  const [isLoadingPendingRequests, setIsLoadingPendingRequests] = useState(true)
  const [isLoadingReport, setIsLoadingReport] = useState(false)
  const [isLifting, setIsLifting] = useState(false)
  const [pendingActionClientId, setPendingActionClientId] = useState<number | null>(null)
  const [rejectTarget, setRejectTarget] = useState<PendingLiftRequestDTO | null>(null)
  const [rejectReason, setRejectReason] = useState("")
  const [isRejecting, setIsRejecting] = useState(false)
  const [selectedClient, setSelectedClient] = useState<ClientBlacklistDTO | null>(null)
  const [liftReason, setLiftReason] = useState("")

  const loadClients = useCallback(async () => {
    if (!token) {
      setIsLoadingClients(false)
      return
    }

    setIsLoadingClients(true)
    try {
      const result = await getBlacklistedClients(token)
      setClients(result)
      setError("")
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "Impossible de charger la blacklist.")
    } finally {
      setIsLoadingClients(false)
    }
  }, [token])

  const loadPendingRequests = useCallback(async () => {
    if (!token) {
      setIsLoadingPendingRequests(false)
      return
    }

    setIsLoadingPendingRequests(true)
    try {
      const result = await getPendingLiftRequests(token)
      setPendingRequests(result)
      setError("")
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : "Impossible de charger les demandes de levee.")
    } finally {
      setIsLoadingPendingRequests(false)
    }
  }, [token])

  const loadReport = useCallback(async () => {
    if (!token) {
      return
    }

    setIsLoadingReport(true)
    try {
      const result = await getBlacklistMonthlyReport(token, year, month)
      setReport(result)
      setError("")
    } catch (reportError) {
      setError(reportError instanceof Error ? reportError.message : "Impossible de charger le rapport.")
    } finally {
      setIsLoadingReport(false)
    }
  }, [month, token, year])

  useEffect(() => {
    void loadClients()
  }, [loadClients])

  useEffect(() => {
    void loadPendingRequests()
  }, [loadPendingRequests])

  useEffect(() => {
    void loadReport()
  }, [loadReport])

  useEffect(() => {
    if (!toast) {
      return
    }
    const timeoutId = window.setTimeout(() => setToast(""), 3500)
    return () => window.clearTimeout(timeoutId)
  }, [toast])

  const filteredClients = useMemo(() => {
    const normalizedSearch = search.trim().toLowerCase()

    return clients.filter((client) => {
      const matchesSearch = !normalizedSearch || [
        client.email,
        client.phone,
        client.motif,
        client.livreur_nom,
        String(client.client_id),
      ].some((value) => (value || "").toLowerCase().includes(normalizedSearch))

      const matchesSource = !sourceFilter || (client.source || "").toUpperCase() === sourceFilter

      return matchesSearch && matchesSource
    })
  }, [clients, search, sourceFilter])

  const newThisMonth = useMemo(() => {
    return clients.filter((client) => {
      if (!client.date_blacklist) {
        return false
      }
      const date = new Date(client.date_blacklist)
      return date.getFullYear() === year && date.getMonth() + 1 === month
    }).length
  }, [clients, month, year])

  const totalPerte = useMemo(() => {
    if (report) {
      return report.total_perte
    }
    return clients.reduce((sum, client) => sum + (client.montant_perdu || 0), 0)
  }, [clients, report])

  const canExportReport = Boolean(report && report.commandes_refusees.length > 0)

  const submitLift = async () => {
    if (!token || !selectedClient) {
      return
    }

    setIsLifting(true)
    try {
      await liftBlacklist(token, selectedClient.client_id, liftReason.trim() || undefined)
      setToast(`Blacklist leve pour ${selectedClient.email || selectedClient.phone || `client #${selectedClient.client_id}`}.`)
      setSelectedClient(null)
      setLiftReason("")
      await loadClients()
      await loadPendingRequests()
    } catch (liftError) {
      setError(
        liftError instanceof ApiError || liftError instanceof Error
          ? liftError.message
          : "Impossible de lever le blacklist."
      )
    } finally {
      setIsLifting(false)
    }
  }

  const liftPendingRequest = async (request: PendingLiftRequestDTO) => {
    if (!token) {
      return
    }

    setPendingActionClientId(request.client_id)
    try {
      await liftBlacklist(token, request.client_id, "Demande de levee acceptee")
      setToast(`Restriction levee pour ${request.client_label || request.phone || `client #${request.client_id}`}.`)
      await loadClients()
      await loadPendingRequests()
    } catch (liftError) {
      setError(
        liftError instanceof ApiError || liftError instanceof Error
          ? liftError.message
          : "Impossible de lever le blacklist."
      )
    } finally {
      setPendingActionClientId(null)
    }
  }

  const submitReject = async () => {
    if (!token || !rejectTarget) {
      return
    }

    const normalizedReason = rejectReason.trim()
    if (!normalizedReason) {
      setError("Motif de rejet obligatoire.")
      return
    }

    setIsRejecting(true)
    try {
      await rejectLiftRequest(token, rejectTarget.client_id, normalizedReason)
      setToast(`Demande rejetee pour ${rejectTarget.client_label || rejectTarget.phone || `client #${rejectTarget.client_id}`}.`)
      setRejectTarget(null)
      setRejectReason("")
      await loadPendingRequests()
    } catch (rejectError) {
      setError(
        rejectError instanceof ApiError || rejectError instanceof Error
          ? rejectError.message
          : "Impossible de rejeter la demande."
      )
    } finally {
      setIsRejecting(false)
    }
  }

  return (
    <div className="min-h-screen bg-[#F5F5F0]">
      {toast && (
        <div className="fixed right-5 top-5 z-[70] flex items-center gap-3 rounded-2xl border border-emerald-100 bg-white px-5 py-4 text-sm font-semibold text-[#1E8A3C] shadow-xl">
          <CheckCircle2 className="h-5 w-5" />
          {toast}
        </div>
      )}

      <header className="sticky top-0 z-20 border-b border-gray-200 bg-white/95 px-6 py-4 backdrop-blur-sm">
        <div className="flex items-center justify-between gap-4">
          <div className="flex min-w-0 items-center gap-4">
            <Link href="/admin" className="flex items-center gap-2 rounded-lg px-2 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 hover:text-[#1E8A3C]">
              <ArrowLeft className="h-4 w-4" />
              <span className="hidden sm:inline">Retour</span>
            </Link>
            <div className="flex min-w-0 items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl border border-red-100 bg-red-50 text-red-700">
                <ShieldAlert className="h-5 w-5" />
              </div>
              <div className="min-w-0">
                <h1 className="truncate text-xl font-semibold tracking-tight text-gray-900">Gestion Blacklist COD</h1>
                <p className="hidden text-xs text-gray-500 md:block">Clients bloques pour paiement COD</p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <p className="hidden text-sm font-medium capitalize text-gray-500 md:block">{formatToday()}</p>
            <button
              type="button"
              onClick={() => {
                void loadClients()
                void loadPendingRequests()
              }}
              disabled={isLoadingClients || isLoadingPendingRequests}
              className="inline-flex items-center justify-center gap-2 rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm font-medium text-gray-700 transition-all duration-150 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-60"
            >
              <RefreshCw className={cn("h-4 w-4 text-[#1E8A3C]", (isLoadingClients || isLoadingPendingRequests) && "animate-spin")} />
              <span className="hidden lg:inline">Actualiser</span>
            </button>
          </div>
        </div>
      </header>

      <aside className="fixed left-0 top-[73px] z-10 hidden h-[calc(100vh-73px)] w-56 flex-col border-r border-gray-100 bg-white lg:flex">
        <nav className="flex-1 space-y-1 overflow-y-auto p-4">
          {[
            { id: "liste" as const, label: "Liste blacklistes", icon: UserX, count: clients.length },
            { id: "rapport" as const, label: "Rapport mensuel", icon: FileBarChart, count: null },
          ].map((item) => {
            const isActive = activeSection === item.id
            const Icon = item.icon

            return (
              <button
                key={item.id}
                type="button"
                onClick={() => setActiveSection(item.id)}
                className={cn(
                  "inline-flex w-full items-center justify-between rounded-lg px-3 py-2 text-sm font-medium transition-all duration-150",
                  isActive ? "bg-[#F0FDF4] text-[#1E8A3C]" : "text-gray-600 hover:bg-gray-100 hover:text-gray-900"
                )}
              >
                <span className="inline-flex items-center gap-2">
                  <Icon className="h-4 w-4" aria-hidden="true" />
                  {item.label}
                </span>
                {item.count !== null ? (
                  <span className={cn("rounded-full px-2 py-0.5 text-xs", isActive ? "bg-white text-[#1E8A3C]" : "bg-gray-100 text-gray-500")}>
                    {item.count}
                  </span>
                ) : null}
              </button>
            )
          })}
        </nav>
      </aside>

      <main className="lg:pl-56">
        {error && (
          <div className="mx-6 mt-6 rounded-2xl border border-red-200 bg-red-50 px-5 py-4">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div className="flex items-start gap-3 text-sm font-medium text-red-700">
                <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0" />
                <span>Impossible de charger les donnees. {error}</span>
              </div>
              <button
                type="button"
                onClick={() => {
                  void loadClients()
                  void loadPendingRequests()
                }}
                className="inline-flex items-center gap-2 rounded-lg border border-red-200 bg-white px-3 py-2 text-sm font-medium text-red-700 transition hover:bg-red-50"
              >
                Reessayer
                <ChevronRight className="h-4 w-4" />
              </button>
            </div>
          </div>
        )}

        <section className="grid grid-cols-1 gap-4 border-b border-gray-100 bg-white px-6 py-4 sm:grid-cols-2 xl:grid-cols-4">
          <KpiCard icon={UserX} label="Blacklistes" value={clients.length} helper="Total actif" tone="red" />
          <KpiCard icon={CalendarDays} label="Refus ce mois" value={report?.total_refus ?? newThisMonth} helper={`${monthLabels[month - 1]} ${year}`} tone="orange" />
          <KpiCard icon={Banknote} label="Perte totale" value={formatMoney(totalPerte)} helper="Montant en DH" tone="green" />
          <KpiCard icon={BarChart3} label="Commandes refusées" value={report?.commandes_refusees.length ?? 0} helper="Rapport sélectionné" tone="blue" />
        </section>

        <div className="px-6 py-6">
          <div className="min-w-0">
            <div className={cn(activeSection !== "liste" && "hidden")}>
              <SectionShell>
                <div className="border-b border-gray-100 px-5 py-4">
                  <div>
                    <h2 className="text-lg font-bold tracking-tight text-gray-950">Clients blacklistes</h2>
                    <p className="mt-1 text-sm text-gray-500">Comptes actuellement bloques pour les commandes COD.</p>
                  </div>
                </div>

                <div className="flex items-center gap-3 border-b border-gray-100 bg-gray-50/50 px-5 py-4">
                    <label className="relative max-w-sm flex-1">
                      <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
                      <input
                        value={search}
                        onChange={(event) => setSearch(event.target.value)}
                        placeholder="Rechercher par email, telephone..."
                        className="w-full rounded-lg border border-gray-200 bg-white py-2 pl-9 pr-4 text-sm text-gray-700 outline-none transition-all duration-150 placeholder:text-gray-400 focus:border-[#1E8A3C] focus:ring-2 focus:ring-[#1E8A3C]/20"
                      />
                    </label>

                    <select
                      value={sourceFilter}
                      onChange={(event) => setSourceFilter(event.target.value)}
                      className="cursor-pointer appearance-none rounded-lg border border-gray-200 bg-white py-2 pl-3 pr-8 text-sm text-gray-700 outline-none transition-all duration-150 focus:border-[#1E8A3C] focus:ring-2 focus:ring-[#1E8A3C]/20"
                    >
                      <option value="">Toutes sources</option>
                      <option value="AUTO_REFUS">Automatique</option>
                      <option value="ADMIN">Admin</option>
                    </select>
                </div>

                {isLoadingClients ? (
                  <TableSkeleton columns={8} />
                ) : filteredClients.length === 0 ? (
                  <EmptyState
                    icon={CheckCircle2}
                    title="Aucun client blackliste"
                    description="Tous les comptes peuvent passer des commandes COD."
                  />
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full">
                      <thead className="border-b border-gray-200 bg-gray-50">
                        <tr>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Client</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Téléphone</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Date</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Source</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Commande refusee</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Perte</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Livreur</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-gray-500">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-100">
                        {filteredClients.map((client) => (
                          <tr key={client.client_id} className="group transition-colors duration-100 hover:bg-gray-50/80">
                            <td className="px-5 py-4 text-sm text-gray-700">
                              <div className="flex flex-col gap-2">
                                <div className="flex flex-wrap items-center gap-2">
                                  <p className="font-medium text-gray-950">{emptyValue(getClientLabel(client))}</p>
                                  <BlacklistBadge />
                                </div>
                                <p className="text-xs text-gray-400">ID client #{client.client_id}</p>
                              </div>
                            </td>
                            <td className="px-5 py-4 text-sm text-gray-700">{emptyValue(client.phone)}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">{formatDate(client.date_blacklist)}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">
                              <div className="flex flex-col gap-1.5">
                                <SourceBadge source={client.source} />
                                <span className="text-xs text-gray-400">{emptyValue(client.motif)}</span>
                              </div>
                            </td>
                            <td className="px-5 py-4 text-sm text-gray-700">
                              <div className="flex flex-col gap-1">
                                <span className="font-semibold text-[#1E8A3C]">
                                  {client.commande_id ? `#${client.commande_id}` : "-"}
                                </span>
                                <span className="text-xs text-gray-400">{formatDate(client.commande_date)}</span>
                                {client.commande_statut ? <span className="text-xs text-gray-400">{client.commande_statut}</span> : null}
                              </div>
                            </td>
                            <td className="px-5 py-4 text-sm font-semibold text-[#F07C00]">{formatMoney(client.montant_perdu)}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">{emptyValue(client.livreur_nom)}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">
                              <button
                                type="button"
                                onClick={() => {
                                  setSelectedClient(client)
                                  setLiftReason("")
                                }}
                                className="inline-flex items-center gap-1.5 rounded-lg border border-[#BBF7D0] bg-[#F0FDF4] px-3 py-1.5 text-xs font-semibold text-[#1E8A3C] shadow-sm transition-all duration-150 hover:border-[#1E8A3C] hover:bg-[#1E8A3C] hover:text-white hover:shadow"
                              >
                                <CheckCircle2 className="h-3.5 w-3.5" />
                                Lever
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </SectionShell>

              <SectionShell className="mt-6 border-amber-200 bg-amber-50">
                <div className="border-b border-amber-200 px-5 py-4">
                  <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                    <div>
                      <h2 className="text-lg font-bold tracking-tight text-amber-900">Demandes de levee en attente</h2>
                      <p className="mt-1 text-sm text-amber-700">Demandes envoyees par les clients blacklistes.</p>
                    </div>
                    {pendingRequests.length > 0 ? (
                      <span className="inline-flex w-fit items-center rounded-full bg-amber-500 px-2.5 py-1 text-xs font-bold text-white">
                        {pendingRequests.length}
                      </span>
                    ) : null}
                  </div>
                </div>

                {isLoadingPendingRequests ? (
                  <TableSkeleton columns={5} rows={3} />
                ) : pendingRequests.length === 0 ? (
                  <EmptyState
                    icon={ShieldCheck}
                    title="Aucune demande en attente"
                    description="Les nouvelles demandes de levee apparaitront ici."
                  />
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full">
                      <thead className="border-b border-amber-200 bg-amber-100/60">
                        <tr>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-amber-800">Client</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-amber-800">Telephone</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-amber-800">Motif</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-amber-800">Date demande</th>
                          <th className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-amber-800">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-amber-100 bg-white/70">
                        {pendingRequests.map((request) => (
                          <tr key={request.log_id} className="transition-colors duration-100 hover:bg-amber-50/80">
                            <td className="px-5 py-4 text-sm font-medium text-gray-950">{emptyValue(request.client_label || `Client #${request.client_id}`)}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">{emptyValue(request.phone)}</td>
                            <td className="max-w-md px-5 py-4 text-sm text-gray-700">{request.motif || "-"}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">{formatDate(request.created_at)}</td>
                            <td className="px-5 py-4 text-sm text-gray-700">
                              <div className="flex flex-wrap gap-2">
                                <button
                                  type="button"
                                  onClick={() => void liftPendingRequest(request)}
                                  disabled={pendingActionClientId === request.client_id}
                                  className="inline-flex items-center gap-1.5 rounded-lg bg-[#1E8A3C] px-3 py-1.5 text-xs font-semibold text-white shadow-sm transition hover:bg-[#176B2E] disabled:cursor-not-allowed disabled:opacity-60"
                                >
                                  {pendingActionClientId === request.client_id ? <Spinner className="size-3.5" /> : <CheckCircle2 className="h-3.5 w-3.5" />}
                                  Lever
                                </button>
                                <button
                                  type="button"
                                  onClick={() => {
                                    setRejectTarget(request)
                                    setRejectReason("")
                                  }}
                                  className="inline-flex items-center gap-1.5 rounded-lg bg-red-500 px-3 py-1.5 text-xs font-semibold text-white shadow-sm transition hover:bg-red-600"
                                >
                                  Rejeter
                                </button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </SectionShell>
            </div>

            <div className={cn(activeSection !== "rapport" && "hidden")}>
              <SectionShell>
                <div className="flex flex-col gap-4 border-b border-gray-100 p-6 lg:flex-row lg:items-end lg:justify-between">
                  <div>
                    <div className="mb-2 inline-flex items-center gap-2 rounded-full bg-[#F0FAF1] px-3 py-1 text-xs font-bold uppercase tracking-[0.18em] text-[#1E8A3C]">
                      <FileBarChart className="h-4 w-4" />
                      Rapport mensuel
                    </div>
                    <h2 className="text-lg font-bold tracking-tight text-gray-950">
                      Rapport du mois de {monthLabels[month - 1]} {year}
                    </h2>
                    <p className="mt-1 text-sm text-gray-500">Analyse des refus par client, livreur et quartier.</p>
                  </div>

                  <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
                    <select
                      value={month}
                      onChange={(event) => setMonth(Number(event.target.value))}
                      className="rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm font-medium text-gray-700 outline-none transition-all duration-150 hover:bg-gray-50 focus:border-[#1E8A3C] focus:ring-4 focus:ring-[#1E8A3C]/10"
                    >
                      {monthLabels.map((label, index) => (
                        <option key={label} value={index + 1}>
                          {label}
                        </option>
                      ))}
                    </select>
                    <input
                      type="number"
                      value={year}
                      onChange={(event) => setYear(Number(event.target.value))}
                      className="w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm font-medium text-gray-700 outline-none transition-all duration-150 hover:bg-gray-50 focus:border-[#1E8A3C] focus:ring-4 focus:ring-[#1E8A3C]/10 sm:w-28"
                    />
                    <button
                      type="button"
                      onClick={() => void loadReport()}
                      disabled={isLoadingReport}
                      className="inline-flex items-center justify-center gap-2 rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm font-medium text-gray-700 transition-all duration-150 hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      {isLoadingReport ? <Loader2 className="h-4 w-4 animate-spin text-[#1E8A3C]" /> : <RefreshCw className="h-4 w-4 text-[#1E8A3C]" />}
                      Actualiser
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        if (report) {
                          exportCSV(report, month, year)
                        }
                      }}
                      disabled={!canExportReport}
                      title={!canExportReport ? "Aucune donnée à exporter" : undefined}
                      className="inline-flex items-center justify-center gap-2 rounded-lg bg-[#1E8A3C] px-4 py-2 text-sm font-medium text-white transition-all duration-150 hover:bg-[#176B2E] disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      <FileBarChart className="h-4 w-4" />
                      Exporter CSV
                      <ChevronRight className="h-4 w-4" />
                    </button>
                  </div>
                </div>

                {isLoadingReport ? (
                  <TableSkeleton columns={4} rows={4} />
                ) : report ? (
                  <div className="space-y-6 p-6">
                    <div className="rounded-2xl border border-orange-100 bg-orange-50 px-5 py-4 text-[#9A5C11]">
                      <div className="flex items-center gap-3">
                        <TriangleAlert className="h-5 w-5" />
                        <p className="font-semibold">
                          {report.total_refus} refus COD sur {monthLabels[report.mois - 1]} {report.annee} - perte totale {formatMoney(report.total_perte)}
                        </p>
                      </div>
                    </div>

                    <div className="grid gap-6 xl:grid-cols-2">
                      <ReportTable title="Par client" icon={UserX} columns={["Client", "Téléphone", "Nb refus", "Montant"]}>
                        {report.par_client.map((row) => (
                          <tr key={row.client_id} className="transition-colors duration-100 hover:bg-gray-50">
                            <td className="px-4 py-3 text-sm font-medium text-gray-950">{emptyValue(row.email || `Client #${row.client_id}`)}</td>
                            <td className="px-4 py-3 text-sm text-gray-700">{emptyValue(row.phone)}</td>
                            <td className="px-4 py-3 text-sm font-semibold text-red-700">{row.nb_refus}</td>
                            <td className="px-4 py-3 text-sm font-semibold text-[#F07C00]">{formatMoney(row.montant_perdu)}</td>
                          </tr>
                        ))}
                      </ReportTable>

                      <ReportTable title="Par livreur" icon={ShieldCheck} columns={["Livreur", "Nb refus"]}>
                        {report.par_livreur.map((row) => (
                          <tr key={row.livreur_id} className="transition-colors duration-100 hover:bg-gray-50">
                            <td className="px-4 py-3 text-sm font-medium text-gray-950">{emptyValue(row.livreur_nom || `Livreur #${row.livreur_id}`)}</td>
                            <td className="px-4 py-3 text-sm font-semibold text-red-700">{row.nb_refus}</td>
                          </tr>
                        ))}
                      </ReportTable>

                      <ReportTable title="Par quartier" icon={CalendarDays} columns={["Quartier", "Nb refus", "Montant perdu"]} className="xl:col-span-2">
                        {report.par_quartier.map((row) => (
                          <tr key={row.quartier || "sans-quartier"} className="transition-colors duration-100 hover:bg-gray-50">
                            <td className="px-4 py-3 text-sm font-medium text-gray-950">{emptyValue(row.quartier || "Sans quartier")}</td>
                            <td className="px-4 py-3 text-sm font-semibold text-red-700">{row.nb_refus}</td>
                            <td className="px-4 py-3 text-sm font-semibold text-[#F07C00]">{formatMoney(row.montant_perdu)}</td>
                          </tr>
                        ))}
                      </ReportTable>
                    </div>

                    <ReportTable
                      title="Commandes refusées"
                      icon={FileBarChart}
                      columns={["Commande", "Client", "Téléphone", "Date refus", "Livreur", "Quartier", "Motif", "Perte"]}
                    >
                      {report.commandes_refusees.map((row) => (
                        <tr key={row.log_id} className="transition-colors duration-100 hover:bg-gray-50">
                          <td className="px-4 py-3 text-sm font-semibold text-[#1E8A3C]">
                            {row.commande_id ? `#${row.commande_id}` : "-"}
                          </td>
                          <td className="px-4 py-3 text-sm font-medium text-gray-950">{emptyValue(row.client_label || `Client #${row.client_id}`)}</td>
                          <td className="px-4 py-3 text-sm text-gray-700">{emptyValue(row.phone)}</td>
                          <td className="px-4 py-3 text-sm text-gray-700">{formatDate(row.date_refus)}</td>
                          <td className="px-4 py-3 text-sm text-gray-700">{emptyValue(row.livreur_nom)}</td>
                          <td className="px-4 py-3 text-sm text-gray-700">{emptyValue(row.quartier || "Sans quartier")}</td>
                          <td className="px-4 py-3 text-sm text-gray-700">{row.motif ?? "—"}</td>
                          <td className="px-4 py-3 text-sm font-semibold text-[#F07C00]">{formatMoney(row.montant_perdu)}</td>
                        </tr>
                      ))}
                    </ReportTable>
                  </div>
                ) : (
                  <EmptyState
                    icon={BarChart3}
                    title="Aucune donnee pour cette periode"
                    description="Selectionnez un mois pour afficher son rapport, puis actualisez si besoin."
                  />
                )}
              </SectionShell>
            </div>
          </div>
        </div>
      </main>

      <AlertDialog
        open={selectedClient !== null}
        onOpenChange={(open) => {
          if (!open && !isLifting) {
            setSelectedClient(null)
            setLiftReason("")
          }
        }}
      >
        <AlertDialogContent className="rounded-2xl border border-gray-200 p-0 shadow-xl">
          <div className="border-b border-gray-100 px-6 py-5">
            <AlertDialogHeader>
              <AlertDialogTitle className="text-lg font-bold text-gray-950">
                Lever le blacklist de {selectedClient ? getClientLabel(selectedClient) : "ce client"} ?
              </AlertDialogTitle>
              <AlertDialogDescription className="text-sm text-gray-500">
                Le client pourra a nouveau passer des commandes COD.
              </AlertDialogDescription>
            </AlertDialogHeader>
          </div>
          <div className="px-6 py-5">
            <textarea
              value={liftReason}
              onChange={(event) => setLiftReason(event.target.value)}
              placeholder="Motif (optionnel)..."
              className="min-h-24 w-full resize-none rounded-xl border border-gray-200 px-4 py-3 text-sm text-gray-700 outline-none transition-all duration-150 focus:border-[#1E8A3C] focus:ring-4 focus:ring-[#1E8A3C]/10"
            />
          </div>
          <AlertDialogFooter className="border-t border-gray-100 bg-gray-50 px-6 py-4">
            <AlertDialogCancel className="rounded-lg border-gray-200 bg-white text-gray-700 hover:bg-gray-50" disabled={isLifting}>
              Annuler
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={(event) => {
                event.preventDefault()
                void submitLift()
              }}
              className="rounded-lg bg-[#1E8A3C] text-white hover:bg-[#176B2E]"
              disabled={isLifting}
            >
              {isLifting ? <Spinner className="size-4" /> : <CheckCircle2 className="h-4 w-4" />}
              Confirmer
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog
        open={rejectTarget !== null}
        onOpenChange={(open) => {
          if (!open && !isRejecting) {
            setRejectTarget(null)
            setRejectReason("")
          }
        }}
      >
        <AlertDialogContent className="rounded-2xl border border-gray-200 p-0 shadow-xl">
          <div className="border-b border-gray-100 px-6 py-5">
            <AlertDialogHeader>
              <AlertDialogTitle className="text-lg font-bold text-gray-950">
                Rejeter la demande de levee ?
              </AlertDialogTitle>
              <AlertDialogDescription className="text-sm text-gray-500">
                Le client restera bloque pour les commandes COD et verra le motif dans son espace.
              </AlertDialogDescription>
            </AlertDialogHeader>
          </div>
          <div className="px-6 py-5">
            <textarea
              value={rejectReason}
              onChange={(event) => setRejectReason(event.target.value)}
              placeholder="Motif obligatoire..."
              className="min-h-24 w-full resize-none rounded-xl border border-gray-200 px-4 py-3 text-sm text-gray-700 outline-none transition-all duration-150 focus:border-red-500 focus:ring-4 focus:ring-red-500/10"
            />
          </div>
          <AlertDialogFooter className="border-t border-gray-100 bg-gray-50 px-6 py-4">
            <AlertDialogCancel className="rounded-lg border-gray-200 bg-white text-gray-700 hover:bg-gray-50" disabled={isRejecting}>
              Annuler
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={(event) => {
                event.preventDefault()
                void submitReject()
              }}
              className="rounded-lg bg-red-500 text-white hover:bg-red-600"
              disabled={isRejecting || rejectReason.trim().length === 0}
            >
              {isRejecting ? <Spinner className="size-4" /> : null}
              Rejeter
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function ReportTable({
  title,
  icon: Icon,
  columns,
  children,
  className,
}: {
  title: string
  icon: typeof UserX
  columns: string[]
  children: ReactNode
  className?: string
}) {
  return (
    <div className={cn("overflow-hidden rounded-2xl border border-gray-200 bg-white", className)}>
      <div className="flex items-center gap-2 border-b border-gray-100 px-4 py-3">
        <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#F0FAF1] text-[#1E8A3C]">
          <Icon className="h-4 w-4" />
        </div>
        <h3 className="font-semibold text-gray-950">{title}</h3>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="border-b border-gray-200 bg-gray-50">
            <tr>
              {columns.map((column) => (
                <th key={column} className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider text-gray-500">
                  {column}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">{children}</tbody>
        </table>
      </div>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useState } from "react"
import Link from "next/link"
import {
  AlertTriangle,
  ArrowLeft,
  ChevronLeft,
  ChevronRight,
  Link2,
  RefreshCw,
  RotateCcw,
  XCircle,
} from "lucide-react"

import { useAuth } from "@/hooks/useAuth"
import {
  AdminCommandeException,
  AdminCommandeExceptionsPage,
  AdminDispatchTournee,
  API_BASE_URL,
  annulerAdminCommande,
  getAdminCommandeExceptions,
  getAdminDispatchTournees,
  reassignerAdminCommandeException,
  replanifierAdminCommande,
} from "@/lib/api"

type PendingAdminAction = {
  commandeId: number
  title: string
  description: string
  confirmLabel: string
  tone: "green" | "red"
  action: () => Promise<unknown>
}

const REASONS = [
  "JOUR_PRECEDENT",
  "BROUILLON",
  "PENDING_NON_VALIDE",
  "ECHEC_LIVRAISON",
  "ABERRANT",
  "ANNULEE",
]

const REASON_LABELS: Record<string, string> = {
  JOUR_PRECEDENT: "Jour précédent",
  BROUILLON: "Brouillon",
  PENDING_NON_VALIDE: "Pending non validé",
  ECHEC_LIVRAISON: "Échec livraison",
  ABERRANT: "Statut aberrant",
  ANNULEE: "Annulée",
}

export default function AdminCommandesExceptionsPage() {
  const { token } = useAuth()
  const [data, setData] = useState<AdminCommandeExceptionsPage | null>(null)
  const [tournees, setTournees] = useState<AdminDispatchTournee[]>([])
  const [raison, setRaison] = useState("")
  const [search, setSearch] = useState("")
  const [dateFrom, setDateFrom] = useState("")
  const [dateTo, setDateTo] = useState("")
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [actingId, setActingId] = useState<number | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [pendingAction, setPendingAction] = useState<PendingAdminAction | null>(null)

  const load = useCallback(async () => {
    if (!token) return
    setLoading(true)
    setError(null)
    try {
      const [exceptions, dispatch] = await Promise.all([
        getAdminCommandeExceptions(token, {
          raison,
          search,
          date_from: dateFrom,
          date_to: dateTo,
          page,
          page_size: 20,
        }),
        getAdminDispatchTournees(token),
      ])
      setData(exceptions)
      setTournees(dispatch.tournees ?? [])
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Chargement impossible.")
    } finally {
      setLoading(false)
    }
  }, [token, raison, search, dateFrom, dateTo, page])

  useEffect(() => {
    void load()
  }, [load])

  const runAction = async (commandeId: number, action: () => Promise<unknown>) => {
    setActingId(commandeId)
    setError(null)
    try {
      await action()
      await load()
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Action impossible.")
    } finally {
      setActingId(null)
    }
  }

  const confirmPendingAction = async () => {
    if (!pendingAction) return
    const action = pendingAction
    setPendingAction(null)
    await runAction(action.commandeId, action.action)
  }

  const renderActions = (item: AdminCommandeException) => (
    <div className="mt-4 grid gap-2 sm:grid-cols-2">

      <select
        value=""
        disabled={actingId === item.id || item.tournee_id === null}
        onChange={(event) => {
          const tourneeId = Number(event.target.value)
          if (tourneeId) {
            void runAction(item.id, () =>
              reassignerAdminCommandeException(token!, item.id, tourneeId),
            )
          }
        }}
        className="rounded-xl border border-[#DDEBDD] bg-white px-3 py-2 text-xs font-bold text-[#264129] disabled:opacity-50"
      >
        <option value="">Réassigner à une tournée</option>
        {tournees.filter((tournee) => tournee.id !== item.tournee_id).map((tournee) => (
          <option key={tournee.id} value={tournee.id}>
            Tournée #{tournee.id} — {tournee.livreur.nom}
          </option>
        ))}
      </select>
      <button
        disabled={actingId === item.id}
        onClick={() =>
          setPendingAction({
            commandeId: item.id,
            title: `Replanifier la commande #${item.id} ?`,
            description: "La commande sera replacee dans le flux de planification.",
            confirmLabel: "Replanifier",
            tone: "green",
            action: () => replanifierAdminCommande(token!, item.id),
          })
        }
        className="inline-flex items-center justify-center gap-1 rounded-xl bg-[#EAF8EC] px-3 py-2 text-xs font-black text-[#1E8A3C] disabled:opacity-50"
      >
        <RotateCcw className="h-3.5 w-3.5" /> Replanifier
      </button>
      <button
        disabled={actingId === item.id}
        onClick={() =>
          setPendingAction({
            commandeId: item.id,
            title: `Annuler definitivement la commande #${item.id} ?`,
            description: "Cette action annule la commande et doit rester exceptionnelle.",
            confirmLabel: "Annuler la commande",
            tone: "red",
            action: () => annulerAdminCommande(token!, item.id),
          })
        }
        className="inline-flex items-center justify-center gap-1 rounded-xl bg-red-50 px-3 py-2 text-xs font-black text-red-600 disabled:opacity-50"
      >
        <XCircle className="h-3.5 w-3.5" /> Annuler
      </button>
    </div>
  )

  return (
    <main className="min-h-screen bg-[#F5F5F0] px-4 py-8">
      <div className="mx-auto max-w-6xl">
        <header className="mb-6 flex items-center gap-3">
          <Link href="/admin" className="rounded-lg p-2 text-[#6F8070] hover:bg-white">
            <ArrowLeft className="h-5 w-5" />
          </Link>
          <div className="flex-1">
            <h1 className="text-xl font-black text-[#264129]">Exceptions / Backlog</h1>
            <p className="text-sm text-[#6F8070]">File de rattrapage administrative, sans suppression.</p>
          </div>
          <button onClick={() => void load()} className="rounded-xl border border-[#DDEBDD] bg-white p-2">
            <RefreshCw className="h-4 w-4 text-[#1E8A3C]" />
          </button>
        </header>

        <section className="mb-5 grid gap-2 rounded-2xl border border-[#DDEBDD] bg-white p-4 md:grid-cols-4">
          <input value={search} onChange={(e) => { setSearch(e.target.value); setPage(1) }} placeholder="Commande, client, ville..." className="rounded-xl border border-[#DDEBDD] px-3 py-2 text-sm" />
          <select value={raison} onChange={(e) => { setRaison(e.target.value); setPage(1) }} className="rounded-xl border border-[#DDEBDD] px-3 py-2 text-sm">
            <option value="">Toutes les raisons</option>
            {REASONS.map((value) => <option key={value} value={value}>{REASON_LABELS[value]}</option>)}
          </select>
          <input type="date" value={dateFrom} onChange={(e) => { setDateFrom(e.target.value); setPage(1) }} className="rounded-xl border border-[#DDEBDD] px-3 py-2 text-sm" />
          <input type="date" value={dateTo} onChange={(e) => { setDateTo(e.target.value); setPage(1) }} className="rounded-xl border border-[#DDEBDD] px-3 py-2 text-sm" />
        </section>

        {error && <div className="mb-4 rounded-xl bg-red-50 px-4 py-3 text-sm font-bold text-red-700">{error}</div>}

        {loading ? (
          <div className="h-48 animate-pulse rounded-2xl bg-[#DDEBDD]" />
        ) : !data?.items.length ? (
          <div className="rounded-2xl border border-dashed border-[#DDEBDD] bg-white py-16 text-center">
            <AlertTriangle className="mx-auto h-10 w-10 text-[#A9B8AA]" />
            <p className="mt-3 font-bold text-[#6F8070]">Aucune exception pour ces filtres.</p>
          </div>
        ) : (
          <div className="grid gap-3 lg:grid-cols-2">
            {data.items.map((item) => (
              <article key={item.id} className="rounded-2xl border border-[#DDEBDD] bg-white p-4 shadow-sm">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <h2 className="font-black text-[#264129]">Commande #{item.id}</h2>
                    <p className="text-sm font-bold text-[#6F8070]">{item.client_nom}</p>
                    <p className="text-xs text-[#6F8070]">{item.ville || "Ville inconnue"} · {item.montant_total.toFixed(2)} DH</p>
                  </div>
                  <span className="rounded-lg bg-[#F5F5F0] px-2 py-1 text-xs font-black text-[#264129]">{item.statut || "NULL"}</span>
                </div>
                <div className="mt-3 flex flex-wrap gap-1">
                  {item.raisons.map((value) => (
                    <span key={value} className="rounded-full bg-amber-50 px-2 py-1 text-[11px] font-bold text-amber-700">
                      {REASON_LABELS[value] || value}
                    </span>
                  ))}
                </div>
                <div className="mt-3 grid grid-cols-2 gap-2 text-xs text-[#6F8070]">
                  <p><Link2 className="mr-1 inline h-3 w-3" />Point Souki</p>
                  <p>Tournée : {item.tournee_id ?? "—"} · Livreur : {item.livreur_id ?? "—"}</p>
                </div>
                {renderActions(item)}
              </article>
            ))}
          </div>
        )}

        {data && data.total_pages > 1 && (
          <div className="mt-5 flex items-center justify-center gap-3">
            <button disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="rounded-xl border border-[#DDEBDD] bg-white p-2 disabled:opacity-40"><ChevronLeft className="h-4 w-4" /></button>
            <span className="text-sm font-bold text-[#6F8070]">Page {data.page} / {data.total_pages}</span>
            <button disabled={page >= data.total_pages} onClick={() => setPage((value) => value + 1)} className="rounded-xl border border-[#DDEBDD] bg-white p-2 disabled:opacity-40"><ChevronRight className="h-4 w-4" /></button>
          </div>
        )}
      </div>

      {pendingAction && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#122018]/55 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-md rounded-3xl border border-[#DDEBDD] bg-white p-5 shadow-[0_30px_90px_rgba(18,32,24,0.25)]">
            <div className="flex items-start gap-3">
              <span className={pendingAction.tone === "red" ? "flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-red-50 text-red-600" : "flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[#EAF8EC] text-[#1E8A3C]"}>
                {pendingAction.tone === "red" ? <XCircle className="h-5 w-5" /> : <RotateCcw className="h-5 w-5" />}
              </span>
              <div className="min-w-0 flex-1">
                <h2 className="text-lg font-black text-[#264129]">{pendingAction.title}</h2>
                <p className="mt-1 text-sm font-semibold leading-6 text-[#6F8070]">{pendingAction.description}</p>
              </div>
            </div>
            <div className="mt-5 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={() => setPendingAction(null)}
                className="rounded-2xl border border-[#DDEBDD] px-5 py-3 text-sm font-bold text-[#607061] hover:bg-[#F7FCF7]"
              >
                Annuler
              </button>
              <button
                type="button"
                onClick={() => void confirmPendingAction()}
                className={pendingAction.tone === "red" ? "rounded-2xl bg-red-600 px-5 py-3 text-sm font-black text-white hover:bg-red-700" : "rounded-2xl bg-[#1E8A3C] px-5 py-3 text-sm font-black text-white hover:bg-[#176B2E]"}
              >
                {pendingAction.confirmLabel}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useState } from "react"
import {
  AlertTriangle,
  ArrowLeftRight,
  Bike,
  CalendarDays,
  CheckCircle2,
  Loader2,
  MapPin,
  Package,
  RefreshCw,
  Route,
  Trash2,
  Zap,
  X,
} from "lucide-react"

import { useAuth } from "@/hooks/useAuth"
import {
  ApiError,
  annulerAdminAnomalie,
  getAdminDispatchTournees,
  reassignAdminDispatchCommande,
  replanifierAdminAnomalie,
  runDailyAdminDispatch,
  type AdminDispatchAnomalie,
  type AdminDispatchCommande,
  type AdminDispatchTournee,
} from "@/lib/api"
import { cn } from "@/lib/utils"

type ReassignTarget = {
  commande: AdminDispatchCommande
  sourceTourneeId: number
} | null

type FournisseurTourneesGroup = {
  key: string
  livreur: AdminDispatchTournee["livreur"]
  tournees: AdminDispatchTournee[]
  totalCommandes: number
  livreurNames: string[]
  pickup: AdminDispatchTournee["pickup"]
}

type DisplayedTournee = AdminDispatchTournee & {
  tourneeIds: number[]
  livreurNames: string[]
}

function todayAsIsoDate() {
  const parts = new Intl.DateTimeFormat("fr-MA", {
    timeZone: "Africa/Casablanca",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(new Date())
  const year = parts.find((part) => part.type === "year")?.value || ""
  const month = parts.find((part) => part.type === "month")?.value || ""
  const day = parts.find((part) => part.type === "day")?.value || ""
  return `${year}-${month}-${day}`
}

function isSameIsoDate(value: string | null | undefined, isoDate: string) {
  return value?.split("T")[0] === isoDate
}

function formatDispatchDate(value: string) {
  const [year, month, day] = value.split("-").map(Number)
  if (!year || !month || !day) {
    return "aujourd'hui"
  }

  const formattedDate = new Intl.DateTimeFormat("fr-MA", {
    weekday: "long",
    day: "2-digit",
    month: "long",
  }).format(new Date(year, month - 1, day, 12))

  return formattedDate.charAt(0).toUpperCase() + formattedDate.slice(1)
}

function formatSimpleDate(value?: string | null) {
  if (!value) {
    return "Date non renseignee"
  }

  const [year, month, day] = value.split("T")[0].split("-").map(Number)
  if (!year || !month || !day) {
    return "Date non renseignee"
  }

  return new Intl.DateTimeFormat("fr-MA", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  }).format(new Date(year, month - 1, day, 12))
}

function formatMoney(value: number | null | undefined) {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return "0.00 DH"
  }
  return `${value.toFixed(2)} DH`
}

function getStatusClassName(status: string) {
  const normalizedStatus = status.toUpperCase()
  if (normalizedStatus === "A_LIVRER") {
    return "bg-[#EAF8EC] text-[#1E8A3C] border-[#BFE6C4]"
  }
  if (normalizedStatus === "EN_ROUTE") {
    return "bg-[#EEF7FF] text-[#1A5F96] border-[#B9D7F2]"
  }
  if (normalizedStatus === "LIVRE") {
    return "bg-[#F0FAF1] text-[#176B2E] border-[#CDE8D0]"
  }
  if (["ABSENT", "REFUS", "ANNULEE"].includes(normalizedStatus)) {
    return "bg-[#FFF1F1] text-[#B42318] border-[#F1C6C6]"
  }
  if (normalizedStatus === "RETOUR_DEPOT") {
    return "bg-[#FFF1F1] text-[#B42318] border-[#F1C6C6]"
  }
  return "bg-[#FFF7EE] text-[#9A5C11] border-[#F5D7B8]"
}

function formatStatus(status: string) {
  const labels: Record<string, string> = {
    EN_ATTENTE_LIVREUR: "En attente livreur",
    A_LIVRER: "A livrer",
    EN_ROUTE: "En route",
    LIVRE: "Livrée",
    ABSENT: "Absent",
    REFUS: "Refusée",
    ANNULEE: "Annulée",
    RETOUR_DEPOT: "Retour depot",
    PLANIFIEE: "Planifiee",
  }
  return labels[status.toUpperCase()] || status || "Inconnu"
}

function isCommandeReassignable(status: string) {
  return ["EN_ATTENTE_LIVREUR", "A_LIVRER", "PLANIFIEE"].includes(status.toUpperCase())
}

export default function AdminLivreurPage() {
  const { token } = useAuth()
  const [dispatchDate, setDispatchDate] = useState(todayAsIsoDate)
  const [tournees, setTournees] = useState<AdminDispatchTournee[]>([])
  const [anomalies, setAnomalies] = useState<AdminDispatchAnomalie[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isRefreshing, setIsRefreshing] = useState(false)
  const [isGeneratingDispatch, setIsGeneratingDispatch] = useState(false)
  const [error, setError] = useState("")
  const [toast, setToast] = useState("")
  const [reassignTarget, setReassignTarget] = useState<ReassignTarget>(null)
  const [selectedTourneeId, setSelectedTourneeId] = useState("")
  const [isSubmittingReassign, setIsSubmittingReassign] = useState(false)
  const [resolvingAnomalieId, setResolvingAnomalieId] = useState<number | null>(null)

  const loadTournees = useCallback(
    async (showLoader = true) => {
      if (!token) {
        setTournees([])
        setAnomalies([])
        setIsLoading(false)
        return
      }

      try {
        if (showLoader) {
          setIsLoading(true)
        } else {
          setIsRefreshing(true)
        }
        const response = await getAdminDispatchTournees(token)
        const today = todayAsIsoDate()
        const todaysTournees = (response.tournees || []).filter((tournee) =>
          isSameIsoDate(tournee.date_tournee, today)
        )
        const todaysAnomalies = (response.anomalies || []).filter((anomalie) =>
          isSameIsoDate(anomalie.detected_at || anomalie.date_tournee_ratee, today)
        )
        setDispatchDate(today)
        setTournees(todaysTournees)
        setAnomalies(todaysAnomalies)
        setError("")
      } catch (loadError) {
        setError(
          loadError instanceof Error
            ? loadError.message
            : "Impossible de charger les tournees."
        )
      } finally {
        setIsLoading(false)
        setIsRefreshing(false)
      }
    },
    [token]
  )

  useEffect(() => {
    void loadTournees(true)
  }, [loadTournees])

  useEffect(() => {
    if (!toast) {
      return
    }
    const timeoutId = window.setTimeout(() => setToast(""), 3500)
    return () => window.clearTimeout(timeoutId)
  }, [toast])

  const totalCommandes = useMemo(
    () => tournees.reduce((sum, tournee) => sum + tournee.commandes.length, 0),
    [tournees]
  )
  const fournisseurTourneeGroups = useMemo<FournisseurTourneesGroup[]>(() => {
    const groupsByFournisseur = new Map<string, FournisseurTourneesGroup>()

    for (const tournee of tournees) {
      const fournisseurKey =
        tournee.pickup?.fournisseur_id !== null && tournee.pickup?.fournisseur_id !== undefined
          ? `fournisseur-${tournee.pickup.fournisseur_id}`
          : `fournisseur-inconnu-${tournee.id}`
      const existingGroup = groupsByFournisseur.get(fournisseurKey)

      if (existingGroup) {
        existingGroup.tournees.push(tournee)
        existingGroup.totalCommandes += tournee.commandes.length
        if (!existingGroup.livreurNames.includes(tournee.livreur.nom)) {
          existingGroup.livreurNames.push(tournee.livreur.nom)
        }
      } else {
        groupsByFournisseur.set(fournisseurKey, {
          key: fournisseurKey,
          livreur: tournee.livreur,
          tournees: [tournee],
          totalCommandes: tournee.commandes.length,
          livreurNames: [tournee.livreur.nom],
          pickup: tournee.pickup,
        })
      }
    }

    return Array.from(groupsByFournisseur.values())
  }, [tournees])
  const displayedTournees = useMemo<DisplayedTournee[]>(
    () =>
      fournisseurTourneeGroups.map((group) => {
        const firstTournee = group.tournees[0]
        return {
          ...firstTournee,
          livreur: group.livreur,
          commandes: group.tournees.flatMap((tournee) => tournee.commandes),
          tourneeIds: group.tournees.map((tournee) => tournee.id),
          livreurNames: group.livreurNames,
          pickup: group.pickup,
        }
      }),
    [fournisseurTourneeGroups]
  )
  const commandeSourceTourneeIds = useMemo(() => {
    const sourceIds = new Map<number, number>()

    for (const tournee of tournees) {
      for (const commande of tournee.commandes) {
        sourceIds.set(commande.id, tournee.id)
      }
    }

    return sourceIds
  }, [tournees])
  const dispatchDateLabel = useMemo(() => formatDispatchDate(dispatchDate), [dispatchDate])
  const hasAnomalies = anomalies.length > 0
  const hasDispatchData = totalCommandes > 0 || hasAnomalies

  const openReassignModal = (commande: AdminDispatchCommande, sourceTourneeId: number) => {
    const firstOtherTournee = tournees.find((tournee) => tournee.id !== sourceTourneeId)
    setReassignTarget({ commande, sourceTourneeId })
    setSelectedTourneeId(firstOtherTournee ? String(firstOtherTournee.id) : "")
  }

  const closeReassignModal = () => {
    if (isSubmittingReassign) {
      return
    }
    setReassignTarget(null)
    setSelectedTourneeId("")
  }

  const generateDispatch = async () => {
    if (!token) {
      return
    }

    setIsGeneratingDispatch(true)
    try {
      const response = await runDailyAdminDispatch(token)
      const assignedCount = response.commandes_assigned ?? response.count ?? 0
      const tourneeCount = response.tournees_created ?? 0
      setDispatchDate(response.target_date || todayAsIsoDate())
      setToast(
        response.status === "no_orders"
          ? "Aucune commande disponible pour générer un dispatch."
          : `Dispatch généré : ${tourneeCount} tournée${tourneeCount > 1 ? "s" : ""}, ${assignedCount} commande${assignedCount > 1 ? "s" : ""} assignée${assignedCount > 1 ? "s" : ""}.`
      )
      setError("")
      await loadTournees(false)
    } catch (dispatchError) {
      setError(
        dispatchError instanceof ApiError || dispatchError instanceof Error
          ? dispatchError.message
          : "Impossible de générer le dispatch."
      )
    } finally {
      setIsGeneratingDispatch(false)
    }
  }

  const submitReassign = async () => {
    if (!token || !reassignTarget || !selectedTourneeId) {
      return
    }

    const nextTourneeId = Number(selectedTourneeId)
    if (!Number.isFinite(nextTourneeId)) {
      setError("Tournée cible invalide.")
      return
    }

    setIsSubmittingReassign(true)
    try {
      await reassignAdminDispatchCommande(token, reassignTarget.commande.id, nextTourneeId)
      setToast(`Commande #${reassignTarget.commande.id} réassignée avec succès.`)
      setReassignTarget(null)
      setSelectedTourneeId("")
      await loadTournees(false)
    } catch (submitError) {
      setError(
        submitError instanceof ApiError || submitError instanceof Error
          ? submitError.message
          : "Impossible de reassigner la commande."
      )
    } finally {
      setIsSubmittingReassign(false)
    }
  }

  const resolveAnomalie = async (anomalieId: number, action: "replanifier" | "annuler") => {
    if (!token) {
      return
    }

    setResolvingAnomalieId(anomalieId)
    try {
      if (action === "replanifier") {
        await replanifierAdminAnomalie(token, anomalieId)
        setToast("Anomalie resolue: commande remise en attente.")
      } else {
        await annulerAdminAnomalie(token, anomalieId)
        setToast("Anomalie resolue: commande annulee en perte.")
      }
      setError("")
      await loadTournees(false)
    } catch (resolveError) {
      setError(
        resolveError instanceof ApiError || resolveError instanceof Error
          ? resolveError.message
          : "Impossible de resoudre cette anomalie."
      )
    } finally {
      setResolvingAnomalieId(null)
    }
  }

  const availableTargetTournees = reassignTarget
    ? tournees.filter(
        (tournee) =>
          tournee.id !== reassignTarget.sourceTourneeId &&
          isSameIsoDate(tournee.date_tournee, todayAsIsoDate())
      )
    : []

  return (
    <div className="min-h-screen bg-[#F5F5F0]">
      {toast && (
        <div className="fixed right-5 top-5 z-[70] flex items-center gap-3 rounded-2xl border border-[#BFE6C4] bg-white px-5 py-4 text-sm font-semibold text-[#1E8A3C] shadow-xl">
          <CheckCircle2 className="h-5 w-5" />
          {toast}
        </div>
      )}

      <main className="mx-auto max-w-[1600px] px-4 py-8 lg:px-8">
        <section className="mb-8 overflow-hidden rounded-[32px] border border-[#DDEBDD] bg-white shadow-[0_24px_80px_-45px_rgba(30,138,60,0.35)]">
          <div className="bg-gradient-to-r from-[#123A1D] via-[#1E8A3C] to-[#F07C00] p-6 text-white lg:p-8">
            <div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between">
              <div>
                <div className="mb-3 inline-flex items-center gap-2 rounded-full bg-white/15 px-3 py-1 text-xs font-bold uppercase tracking-[0.2em]">
                  <Route className="h-4 w-4" />
                  Dispatch logistique
                </div>
                <h1 className="text-3xl font-black lg:text-5xl">Tournees livreurs</h1>
                <p className="mt-3 max-w-2xl text-sm text-white/80 lg:text-base">
                  Supervision des tournées planifiées, commandes assignées et réassignations rapides.
                </p>
                <p className="mt-4 inline-flex items-center gap-2 rounded-full bg-white/15 px-4 py-2 text-sm font-bold text-white">
                  <CalendarDays className="h-4 w-4" />
                  Dispatch du {dispatchDateLabel}
                </p>
              </div>

              <div className="grid gap-3 sm:grid-cols-3">
                <div className="rounded-3xl bg-white/15 px-5 py-4 backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.18em] text-white/65">Tournees</p>
                  <p className="mt-1 text-3xl font-black">{tournees.length}</p>
                </div>
                <div className="rounded-3xl bg-white/15 px-5 py-4 backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.18em] text-white/65">Commandes</p>
                  <p className="mt-1 text-3xl font-black">{totalCommandes}</p>
                </div>
                <div className="rounded-3xl bg-red-500/25 px-5 py-4 backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.18em] text-white/75">Inspections</p>
                  <p className="mt-1 text-3xl font-black">{anomalies.length}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex flex-col gap-2 text-sm font-semibold text-[#264129] sm:flex-row sm:items-center">
              <span className="inline-flex items-center gap-2">
                <CalendarDays className="h-4 w-4 text-[#1E8A3C]" />
                Jour courant
              </span>
              <span className="rounded-2xl border border-[#D7EBD9] bg-[#FAFCFA] px-4 py-3 text-[#264129]">
                Dispatch du {dispatchDateLabel}
              </span>
            </div>

            <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
              <button
                onClick={() => void generateDispatch()}
                disabled={isGeneratingDispatch || isRefreshing || isLoading}
                className="inline-flex items-center justify-center gap-2 rounded-2xl bg-[#F07C00] px-5 py-3 font-bold text-white transition hover:bg-[#D66B00] disabled:cursor-not-allowed disabled:opacity-60"
              >
                {isGeneratingDispatch ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Zap className="h-4 w-4" />
                )}
                Generer le Dispatch
              </button>

              <button
                onClick={() => void loadTournees(false)}
                disabled={isRefreshing || isLoading || isGeneratingDispatch}
                className="inline-flex items-center justify-center gap-2 rounded-2xl bg-[#1E8A3C] px-5 py-3 font-bold text-white transition hover:bg-[#176B2E] disabled:cursor-not-allowed disabled:opacity-60"
              >
                <RefreshCw className={cn("h-4 w-4", isRefreshing && "animate-spin")} />
                Rafraîchir
              </button>
            </div>
          </div>
        </section>

        {error && (
          <div className="mb-6 rounded-2xl border border-red-200 bg-red-50 px-5 py-4 text-sm font-semibold text-red-600">
            {error}
          </div>
        )}

        {isLoading ? (
          <div className="min-h-[360px] space-y-4 rounded-[32px] border border-[#DDEBDD] bg-white p-6" role="status" aria-label="Chargement des tournées">
            <div className="souki-skeleton h-8 w-56 rounded-xl" />
            {Array.from({ length: 3 }).map((_, index) => (
              <div key={index} className="souki-skeleton h-24 rounded-2xl" />
            ))}
          </div>
        ) : !hasDispatchData ? (
          <div className="flex min-h-[360px] items-center justify-center rounded-[32px] border border-[#DDEBDD] bg-white p-8 text-center">
            <div>
              <Package className="mx-auto h-12 w-12 text-[#C8D9CA]" />
              <h2 className="mt-4 text-xl font-black text-[#264129]">
                Aucune commande ou tournée générée pour aujourd'hui.
              </h2>
              <p className="mt-2 text-[#6F8070]">
                Cliquez sur "Generer le Dispatch" pour commencer.
              </p>
              <button
                onClick={() => void generateDispatch()}
                disabled={isGeneratingDispatch || isRefreshing}
                className="mt-6 inline-flex items-center justify-center gap-2 rounded-2xl bg-[#F07C00] px-5 py-3 font-bold text-white transition hover:bg-[#D66B00] disabled:cursor-not-allowed disabled:opacity-60"
              >
                {isGeneratingDispatch ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Zap className="h-4 w-4" />
                )}
                Generer le Dispatch
              </button>
            </div>
          </div>
        ) : (
          <>
            {hasAnomalies && (
              <section className="mb-6 rounded-[32px] border-2 border-red-300 bg-red-50 p-5 shadow-[0_20px_70px_-45px_rgba(180,35,24,0.5)]">
                <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                  <div>
                    <div className="inline-flex items-center gap-2 rounded-full border border-red-200 bg-white px-3 py-1 text-xs font-black uppercase tracking-[0.18em] text-red-700">
                      <AlertTriangle className="h-4 w-4" />
                      Retour depot
                    </div>
                    <h2 className="mt-3 text-2xl font-black text-red-900">
                      Inspections marchandise en attente
                    </h2>
                  </div>
                  <span className="inline-flex items-center justify-center rounded-full bg-red-600 px-4 py-2 text-sm font-black text-white">
