                </div>

                <div className="grid gap-4 xl:grid-cols-2">
                  {anomalies.map((anomalie) => {
                    const commande = anomalie.commande
                    const produits = commande?.produits || []
                    const isResolving = resolvingAnomalieId === anomalie.id

