                      <article
                        key={anomalie.id}
                        className="rounded-[24px] border border-red-200 bg-white p-5 shadow-sm"
                      >
                        <div className="flex flex-wrap items-start justify-between gap-3">
                          <div>
                            <p className="text-xs font-black uppercase tracking-[0.16em] text-red-500">
