"use client"

import { FormEvent, useCallback, useEffect, useState } from "react"
import Link from "next/link"
import { ChevronLeft, MapPinned, Pencil, Plus, Power, RefreshCw, X } from "lucide-react"

import { useAuth } from "@/hooks/useAuth"
import { API_BASE_URL } from "@/lib/api"

type Zone = {
  id: number
  nom_ville: string
  lat_centre: number
  lng_centre: number
  rayon_km: number
  actif: boolean
}


type ZoneForm = {
  nom_ville: string
  lat_centre: string
  lng_centre: string
  rayon_km: string
  actif: boolean
}

const EMPTY_FORM: ZoneForm = {
  nom_ville: "",
  lat_centre: "",
  lng_centre: "",
  rayon_km: "25",
  actif: true,
}

export default function AdminZonesPage() {
  const { token } = useAuth()
  const [zones, setZones] = useState<Zone[]>([])
  const [form, setForm] = useState<ZoneForm>(EMPTY_FORM)
  const [editingId, setEditingId] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const loadData = useCallback(async () => {
    if (!token) return
    setLoading(true)
    setError(null)
    try {
      const headers = { Authorization: `Bearer ${token}` }
      const zonesResponse = await fetch(`${API_BASE_URL}/api/admin/zones`, {headers, cache: "no-store"})
      if (!zonesResponse.ok) throw new Error("Impossible de charger les zones.")
      setZones(await zonesResponse.json())
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Erreur de chargement.")
    } finally {
      setLoading(false)
    }
  }, [token])

  useEffect(() => {
    void loadData()
  }, [loadData])

  const resetForm = () => {
    setEditingId(null)
    setForm(EMPTY_FORM)
  }

  const editZone = (zone: Zone) => {
    setEditingId(zone.id)
    setForm({
      nom_ville: zone.nom_ville,
      lat_centre: String(zone.lat_centre),
      lng_centre: String(zone.lng_centre),
      rayon_km: String(zone.rayon_km),
      actif: zone.actif,
    })
    window.scrollTo({ top: 0, behavior: "smooth" })
  }

  const submitZone = async (event: FormEvent) => {
    event.preventDefault()
    if (!token) return
    setSaving(true)
    setError(null)
    try {
      const response = await fetch(
        `${API_BASE_URL}/api/admin/zones${editingId ? `/${editingId}` : ""}`,
        {
          method: editingId ? "PUT" : "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            nom_ville: form.nom_ville.trim(),
            lat_centre: Number(form.lat_centre),
            lng_centre: Number(form.lng_centre),
            rayon_km: Number(form.rayon_km),
            actif: form.actif,
          }),
        },
      )
      if (!response.ok) {
        const payload = await response.json().catch(() => ({}))
        throw new Error(payload.detail ?? "Enregistrement impossible.")
      }
      resetForm()
      await loadData()
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Enregistrement impossible.")
    } finally {
      setSaving(false)
    }
  }

  const deactivateZone = async (zoneId: number) => {
    if (!token) return
    setError(null)
    try {
      const response = await fetch(`${API_BASE_URL}/api/admin/zones/${zoneId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!response.ok) throw new Error("Désactivation impossible.")
      await loadData()
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : "Désactivation impossible.")
    }
  }

  return (
    <main className="min-h-screen bg-[#F5F5F0] px-4 py-8">
      <div className="mx-auto max-w-5xl">
        <header className="mb-6 flex items-center gap-3">
          <Link href="/admin" className="rounded-lg p-2 text-[#6F8070] hover:bg-white">
            <ChevronLeft className="h-5 w-5" />
          </Link>
          <div className="flex-1">
            <h1 className="text-xl font-black text-[#264129]">Zones de livraison</h1>
            <p className="text-sm text-[#6F8070]">Définissez les zones desservies depuis le point Souki.</p>
          </div>
          <button onClick={() => void loadData()} className="rounded-xl border border-[#DDEBDD] bg-white p-2">
            <RefreshCw className="h-4 w-4 text-[#1E8A3C]" />
          </button>
        </header>

        {error && <div className="mb-4 rounded-xl bg-red-50 px-4 py-3 text-sm font-bold text-red-700">{error}</div>}

        <form onSubmit={submitZone} className="mb-6 rounded-2xl border border-[#DDEBDD] bg-white p-5 shadow-sm">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="flex items-center gap-2 font-black text-[#264129]">
              <Plus className="h-4 w-4 text-[#1E8A3C]" />
              {editingId ? "Modifier la zone" : "Créer une zone"}
            </h2>
            {editingId && (
              <button type="button" onClick={resetForm} className="rounded-lg p-1 text-[#6F8070]">
                <X className="h-4 w-4" />
              </button>
            )}
          </div>

          <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
            <input required value={form.nom_ville} onChange={(e) => setForm({ ...form, nom_ville: e.target.value })} placeholder="Ville / nom de zone" className="rounded-xl border border-[#DDEBDD] px-3 py-2.5 text-sm outline-none focus:border-[#1E8A3C]" />
            <input required type="number" step="any" min="-90" max="90" value={form.lat_centre} onChange={(e) => setForm({ ...form, lat_centre: e.target.value })} placeholder="Latitude du centre" className="rounded-xl border border-[#DDEBDD] px-3 py-2.5 text-sm outline-none focus:border-[#1E8A3C]" />
            <input required type="number" step="any" min="-180" max="180" value={form.lng_centre} onChange={(e) => setForm({ ...form, lng_centre: e.target.value })} placeholder="Longitude du centre" className="rounded-xl border border-[#DDEBDD] px-3 py-2.5 text-sm outline-none focus:border-[#1E8A3C]" />
            <input required type="number" step="0.1" min="0.1" max="500" value={form.rayon_km} onChange={(e) => setForm({ ...form, rayon_km: e.target.value })} placeholder="Rayon (km)" className="rounded-xl border border-[#DDEBDD] px-3 py-2.5 text-sm outline-none focus:border-[#1E8A3C]" />
            <label className="flex items-center gap-2 rounded-xl border border-[#DDEBDD] px-3 py-2.5 text-sm font-bold text-[#264129]">
              <input type="checkbox" checked={form.actif} onChange={(e) => setForm({ ...form, actif: e.target.checked })} />
              Zone active
            </label>
          </div>

          <button disabled={saving} className="mt-4 rounded-xl bg-[#1E8A3C] px-5 py-2.5 text-sm font-black text-white disabled:opacity-50">
            {saving ? "Enregistrement..." : editingId ? "Enregistrer les modifications" : "Créer la zone"}
          </button>
        </form>

        {loading ? (
          <div className="h-40 animate-pulse rounded-2xl bg-[#DDEBDD]" />
        ) : zones.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-[#DDEBDD] bg-white py-14 text-center">
            <MapPinned className="mx-auto mb-2 h-9 w-9 text-[#A9B8AA]" />
            <p className="font-bold text-[#6F8070]">Aucune zone configurée.</p>
          </div>
        ) : (
          <div className="grid gap-3 md:grid-cols-2">
            {zones.map((zone) => (
              <article key={zone.id} className="rounded-2xl border border-[#DDEBDD] bg-white p-4 shadow-sm">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <h2 className="font-black capitalize text-[#264129]">{zone.nom_ville}</h2>
                    <p className="text-xs text-[#6F8070]">{zone.lat_centre}, {zone.lng_centre} · rayon {zone.rayon_km} km</p>
                    <p className="mt-2 text-sm font-bold text-[#1E8A3C]">Point de ramassage Souki</p>
                  </div>
                  <span className={`rounded-lg px-2 py-1 text-xs font-bold ${zone.actif ? "bg-green-100 text-green-700" : "bg-gray-100 text-gray-600"}`}>
                    {zone.actif ? "Active" : "Inactive"}
                  </span>
                </div>
                <div className="mt-3 flex gap-2 border-t border-[#DDEBDD] pt-3">
                  <button onClick={() => editZone(zone)} className="inline-flex items-center gap-1 rounded-lg bg-[#EAF8EC] px-3 py-1.5 text-xs font-bold text-[#1E8A3C]">
                    <Pencil className="h-3.5 w-3.5" /> Modifier
                  </button>
                  {zone.actif && (
                    <button onClick={() => void deactivateZone(zone.id)} className="inline-flex items-center gap-1 rounded-lg bg-amber-50 px-3 py-1.5 text-xs font-bold text-amber-700">
                      <Power className="h-3.5 w-3.5" /> Désactiver
                    </button>
                  )}
                </div>
              </article>
            ))}
          </div>
        )}
      </div>
    </main>
  )
}

"use client"

import { SoukiLogo } from "@/components/souki/souki-logo"
import { useEffect, useMemo, useState } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"

import { useAuth } from "@/hooks/useAuth"
import { canAccessRoute, getAccessDeniedMessage, normalizePath } from "@/lib/routes"

function buildRedirectUrl(targetPath: string, currentPath: string, reason: string) {
  const target = new URL(targetPath, window.location.origin)
  const current = new URL(`${currentPath}${window.location.search}`, window.location.origin)

  if (normalizePath(target.pathname) !== normalizePath(current.pathname)) {
    target.searchParams.set("redirect", `${current.pathname}${current.search}`)
  }
  target.searchParams.set("access_error", reason)
  return `${target.pathname}${target.search}${target.hash}`
}

export function RouteGuard({ children }: { children: React.ReactNode }) {
  const pathname = usePathname()
  const router = useRouter()
  const searchParams = useSearchParams()
  const { isLoading, isAuthenticated, user } = useAuth()
  const [accessError, setAccessError] = useState<string | null>(null)

  const decision = useMemo(
    () => canAccessRoute({ pathname, searchParams, user, isAuthenticated, isLoading }),
    [isAuthenticated, isLoading, pathname, searchParams, user]
  )

  useEffect(() => {
    if (decision.allowed || decision.reason === "loading" || !decision.redirectTo) {
      return
    }

    router.replace(buildRedirectUrl(decision.redirectTo, pathname, decision.reason || "access_denied"))
  }, [decision.allowed, decision.reason, decision.redirectTo, pathname, router])

  useEffect(() => {
    const reason = searchParams.get("access_error")
    setAccessError(reason ? getAccessDeniedMessage(reason as Parameters<typeof getAccessDeniedMessage>[0]) : null)

    if (!reason) {
      return
    }

    const params = new URLSearchParams(searchParams.toString())
    params.delete("access_error")
    params.delete("redirect")

    const nextQuery = params.toString()
    router.replace(nextQuery ? `${pathname}?${nextQuery}` : pathname, { scroll: false })
  }, [pathname, router, searchParams])

  useEffect(() => {
    if (!accessError) {
      return
    }

    const timeoutId = window.setTimeout(() => {
      setAccessError(null)
    }, 3500)

    return () => window.clearTimeout(timeoutId)
  }, [accessError])

  if (decision.allowed) {
    return (
      <>
        {accessError ? (
          <div className="fixed left-1/2 top-4 z-[100] w-[calc(100%-2rem)] max-w-xl -translate-x-1/2 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-800 shadow-lg">
            {accessError}
          </div>
        ) : null}
        {children}
      </>
    )
  }

  return (
    <div className="min-h-screen bg-[#F5F5F0] flex items-center justify-center px-6">
      <div className="max-w-md rounded-3xl border border-[#DDE7DE] bg-white px-8 py-10 text-center shadow-sm">
        <SoukiLogo variant="secondary" height={104} className="mb-4" />
        <h1 className="mt-3 text-2xl font-bold text-[#1E8A3C]">Verification des acces</h1>
        <p className="mt-3 text-sm leading-6 text-[#677669]">Préparation de votre expérience marché</p>
      </div>
    </div>
  )
}

"use client"

import React, { createContext, useContext, useEffect, useState, ReactNode } from "react"
import { toast } from "sonner"
import { API_BASE_URL } from "@/lib/api"

export interface User {
  id: number
  email?: string
  phone?: string
  role: string
  legacy_role?: string | null
  roles: string[]
  permissions: string[]
  is_verified: boolean
  is_active: boolean
  default_dashboard: string
  /** false = compte jamais onboarde. Porte par le serveur, pas par l'appareil. */
  onboarding_completed: boolean
  profiles?: {
    client?: { code_parrainage?: string | null; is_blacklisted?: boolean }
    [key: string]: any
  }
}

interface AuthContextType {
  user: User | null
  token: string | null
  isLoading: boolean
  isAuthenticated: boolean
  login: (loginId: string, password: string, role?: string) => Promise<User>
  adminLogin: (loginId: string, password: string) => Promise<User>
  googleLogin: (googleToken: string, role?: string) => Promise<User>
  logout: () => Promise<void>
  validateToken: () => Promise<boolean>
  hasRole: (role: string) => boolean
  can: (permission: string) => boolean
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)
const AUTH_REQUEST_TIMEOUT_MS = 10000
// Cle de synchronisation inter-onglets (valeur = horodatage, jamais le token).
const AUTH_SYNC_STORAGE_KEY = "souki-auth-sync"
// Marqueur de session non secret expose via useAuth().token quand l'utilisateur est
// connecte. Le vrai JWT vit exclusivement dans le cookie httpOnly.
const COOKIE_SESSION_SENTINEL = "cookie-session"
const NETWORK_RETRY_ATTEMPTS = 3
const NETWORK_RETRY_DELAY_MS = 1200
const NETWORK_TIMEOUT_MS = 5000

const isNetworkFetchError = (error: unknown) =>
  error instanceof TypeError && error.message.toLowerCase().includes("fetch")

const wait = (ms: number) =>
  new Promise((resolve) => {
    window.setTimeout(resolve, ms)
  })

const isRequestTimeoutError = (error: unknown) =>
  error instanceof DOMException && error.name === "AbortError"

function buildApiUnavailableMessage() {
  return `Impossible de joindre l'API (${API_BASE_URL}). Verifiez que le back-end est demarre et accessible depuis le front.`
}

function buildRequestTimeoutMessage() {
  return `L'API met trop de temps a repondre (${API_BASE_URL}). Verifiez que le back-end et la base de donnees sont bien disponibles.`
}

async function readErrorDetail(response: Response) {
  const contentType = response.headers.get("content-type") || ""
  if (!contentType.includes("application/json")) {
    // Reponse non-JSON (page d'erreur HTML d'un proxy/CDN, 5xx, tunnel KO...) :
    // ne JAMAIS exposer ce contenu brut a l'utilisateur. On renvoie null pour que
    // l'appelant affiche un message generique propre.
    return null
  }

  try {
    const payload = await response.json()
    return payload?.detail ? String(payload.detail) : null
  } catch {
    return null
  }
}

async function fetchWithTimeout(
  input: RequestInfo | URL,
  init?: RequestInit,
  timeoutMs = AUTH_REQUEST_TIMEOUT_MS
) {
  const controller = new AbortController()
  const timeoutHandle = window.setTimeout(() => controller.abort(), timeoutMs)

  try {
    return await fetch(input, {
      ...init,
      signal: controller.signal,
    })
  } finally {
    window.clearTimeout(timeoutHandle)
  }
}

function normalizeUser(payload: any): User {
  const roles = Array.isArray(payload?.roles) ? payload.roles.map((value: string) => String(value).toUpperCase()) : []
  const permissions = Array.isArray(payload?.permissions)
    ? payload.permissions.map((value: string) => String(value))
    : []

  return {
    id: Number(payload?.id ?? 0),
    email: payload?.email ?? undefined,
    phone: payload?.phone ?? undefined,
    role: String(payload?.role || payload?.legacy_role || roles[0] || "CLIENT").toUpperCase(),
    legacy_role: payload?.legacy_role ? String(payload.legacy_role).toUpperCase() : null,
    roles,
    permissions,
    is_verified: Boolean(payload?.is_verified),
    is_active: payload?.is_active !== false,
    default_dashboard: String(payload?.default_dashboard || "/"),
    onboarding_completed: Boolean(payload?.onboarding_completed),
    profiles: payload?.profiles && typeof payload.profiles === "object" ? payload.profiles : undefined,
  }
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [token, setToken] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [isAuthenticated, setIsAuthenticated] = useState(false)

  // Source de verite = cookie httpOnly. On interroge /auth/me avec credentials:"include"
  // (le navigateur joint le cookie automatiquement) ; aucun token n'est requis cote JS.
  const fetchCurrentUser = async (): Promise<{ user: User | null; networkError: boolean }> => {
    for (let attempt = 1; attempt <= NETWORK_RETRY_ATTEMPTS; attempt += 1) {
      try {
        const response = await fetchWithTimeout(`${API_BASE_URL}/auth/me`, {
          method: "GET",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
        }, NETWORK_TIMEOUT_MS)

        // Un 401/403 signifie simplement que le visiteur n'a pas de session :
        // le rejouer ne peut pas le reconnecter et surcharge inutilement le backend.
        if (!response.ok) {
          return { user: null, networkError: false }
        }

        const userData = normalizeUser(await response.json())
        setUser(userData)
        return { user: userData, networkError: false }
      } catch (error) {
        const isNetworkError = isRequestTimeoutError(error) || isNetworkFetchError(error)
        if (isNetworkError && attempt < NETWORK_RETRY_ATTEMPTS) {
          await wait(NETWORK_RETRY_DELAY_MS)
          continue
        }

        if (isRequestTimeoutError(error)) {
          toast.error("Le serveur met trop de temps à répondre. Réessayez dans un instant.", {
            id: "auth-network",
          })
          return { user: null, networkError: true }
        }
        if (isNetworkFetchError(error)) {
          toast.error("Service momentanément indisponible. Vérifiez votre connexion.", {
            id: "auth-network",
          })
          return { user: null, networkError: true }
        }
        console.warn(
          "Session refresh error:",
          error instanceof Error ? error.message : String(error)
        )
        return { user: null, networkError: false }
      }
    }

    return { user: null, networkError: true }
  }

  const clearLocalSession = () => {
    setToken(null)
    setUser(null)
    setIsAuthenticated(false)
  }

  // Declenche un evenement "storage" dans les autres onglets pour resynchroniser la session.
  const notifyAuthSync = () => {
    try {
      localStorage.setItem(AUTH_SYNC_STORAGE_KEY, String(Date.now()))
    } catch {
      // localStorage indisponible (mode prive) : la synchro inter-onglets est juste ignoree.
    }
  }

  // Recharge l'utilisateur courant depuis le cookie httpOnly (seule source de verite).
  // nextToken sert uniquement de signal "connexion" (non-null) vs "deconnexion" (null) ;
  // sa valeur reelle est ignoree : le vrai JWT n'est JAMAIS conserve cote JS (anti-XSS).
  const syncAuthState = async (nextToken: string | null): Promise<User | null> => {
    if (nextToken === null) {
      clearLocalSession()
      return null
    }

    const { user: nextUser, networkError } = await fetchCurrentUser()
    if (nextUser) {
      // Marqueur de session NON secret. Les pages qui conditionnent leurs appels sur
      // `token` (ex: supplier, livreur) continuent de fonctionner, et l'en-tete
      // "Authorization: Bearer cookie-session" eventuellement envoye est ignore par le
      // backend (il privilegie le cookie). Le JWT reel reste dans le cookie httpOnly.
      setToken(COOKIE_SESSION_SENTINEL)
      setIsAuthenticated(true)
      return nextUser
    }

    // Ne pas effacer la session si le backend est simplement indisponible temporairement.
    if (networkError) {
      setIsAuthenticated(false)
      return null
    }

    clearLocalSession()
    return null
  }

  // Verifie la session via le cookie, sans token en memoire (init, autres onglets).
  const refreshSession = (): Promise<User | null> => syncAuthState("")

  useEffect(() => {
    const initializeAuth = async () => {
      setIsLoading(true)
      // On tente toujours une reprise de session via le cookie httpOnly.
      await refreshSession()
      setIsLoading(false)
    }

    // Synchronisation inter-onglets : on relaie un signal non sensible (jamais le token).
    const handleStorageChange = async (e: StorageEvent) => {
      if (e.key === AUTH_SYNC_STORAGE_KEY) {
        await refreshSession()
      }
    }

    const handleAuthTokenChanged = async (event: Event) => {
      const customEvent = event as CustomEvent<{ token: string | null }>
      await syncAuthState(customEvent.detail?.token ?? "")
    }

    void initializeAuth()
    window.addEventListener("storage", handleStorageChange)
    window.addEventListener("auth-token-changed", handleAuthTokenChanged as EventListener)

    return () => {
      window.removeEventListener("storage", handleStorageChange)
      window.removeEventListener("auth-token-changed", handleAuthTokenChanged as EventListener)
    }
  }, [])

  const validateToken = async (): Promise<boolean> => {
    return Boolean(await refreshSession())
  }

  const authenticate = async (endpoint: string, payload: Record<string, unknown>) => {
    try {
      let response: Response | null = null

      for (let attempt = 1; attempt <= NETWORK_RETRY_ATTEMPTS; attempt += 1) {
        try {
          response = await fetchWithTimeout(`${API_BASE_URL}${endpoint}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
            // credentials:"include" pour que le navigateur stocke le cookie httpOnly renvoye.
            credentials: "include",
          }, NETWORK_TIMEOUT_MS)
          break
        } catch (error) {
          const isTimeout = isRequestTimeoutError(error)
          if ((isTimeout || isNetworkFetchError(error)) && attempt < NETWORK_RETRY_ATTEMPTS) {
            await wait(NETWORK_RETRY_DELAY_MS)
            continue
          }

          if (isTimeout || isNetworkFetchError(error)) {
            throw new Error("Le serveur backend ne répond pas encore. Attendez 2 à 3 secondes puis réessayez.")
          }

          throw error
        }
      }

      if (!response) {
        throw new Error("Le serveur backend est indisponible.")
      }

      if (!response.ok) {
        const errorDetail = await readErrorDetail(response)
        const fallback =
          response.status >= 500
            ? "Le service est momentanément indisponible. Réessayez dans quelques instants."
            : "Identifiants incorrects ou requête invalide. Vérifiez vos informations."
        throw new Error(errorDetail || fallback)
      }

      const data = await response.json()

      // Chemin rapide : le backend renvoie desormais l'utilisateur complet dans la
      // reponse de login. On evite ainsi un second aller-retour /auth/me (cause du
      // "gel" ressenti pendant plusieurs secondes a la connexion).
      if (data?.user) {
        const nextUser = normalizeUser(data.user)
        setUser(nextUser)
        setToken(COOKIE_SESSION_SENTINEL)
        setIsAuthenticated(true)
        notifyAuthSync()
        return nextUser
      }

      // Repli compatibilite (ancienne API sans champ "user") : on valide via /auth/me.
      const nextUser = await syncAuthState(data.access_token)
      if (!nextUser) {
        throw new Error("Validation du token echouee")
      }
      notifyAuthSync()
      return nextUser
    } catch (error) {
      console.warn(
        "Authentication error:",
        error instanceof Error ? error.message : String(error)
      )
      await syncAuthState(null)
      if (isRequestTimeoutError(error)) {
        throw new Error(buildRequestTimeoutMessage())
      }
      if (isNetworkFetchError(error) || error instanceof TypeError) {
        throw new Error(buildApiUnavailableMessage())
      }
      throw error
    }
  }

  const login = async (loginId: string, password: string, role = "CLIENT") => {
    return authenticate("/auth/login", {
      login_id: loginId,
      password,
      role,
    })
  }

  const adminLogin = async (loginId: string, password: string) => {
    return authenticate("/auth/admin/login", {
      login_id: loginId,
      password,
    })
  }

  const googleLogin = async (googleToken: string, role = "CLIENT") => {
    return authenticate("/auth/google", {
      token: googleToken,
      role,
    })
  }

  const logout = async () => {
    // Invalide la session serveur et supprime le cookie httpOnly.
    try {
      await fetchWithTimeout(`${API_BASE_URL}/auth/logout`, {
        method: "POST",
        credentials: "include",
      }, NETWORK_TIMEOUT_MS)
    } catch {
      // On nettoie l'etat local meme si l'appel reseau echoue.
    }
    await syncAuthState(null)
    notifyAuthSync()
  }

  const hasRole = (role: string) => Boolean(user?.roles.includes(role.toUpperCase()))
  const can = (permission: string) => Boolean(user?.permissions.includes(permission))

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isLoading,
        isAuthenticated,
        login,
        adminLogin,
        googleLogin,
        logout,
        validateToken,
        hasRole,
        can,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

export function useAuthContext() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuthContext must be used within AuthProvider")
  }
  return context
}
